#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    const size_t N = 40000u * 1024u;
    unsigned char *pt = malloc(N);
    unsigned char *ct = malloc(N + 64);
    unsigned char key[32], nonce[12], aad[32], tag[16];
    FILE *f = fopen("/dev/urandom", "rb");
    fread(pt, 1, N, f);
    fread(key, 1, 32, f);
    fread(nonce, 1, 12, f);
    fread(aad, 1, 32, f);
    fclose(f);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *cipher = EVP_chacha20_poly1305();

    int outlen = 0, tmplen = 0;
    /* warmup */
    EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
    EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)N);
    EVP_EncryptFinal_ex(ctx, ct + outlen, &tmplen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);

    double t0 = now();
    int reps = 5;
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)N);
        EVP_EncryptFinal_ex(ctx, ct + outlen, &tmplen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    double t1 = now();
    printf("evp chacha20-poly1305: %.4f s/op  outlen=%d tag0=%02x\n", (t1-t0)/reps, outlen, tag[0]);

    /* ChaCha20 only via EVP_chacha20? */
    const EVP_CIPHER *chacha = EVP_chacha20();
    unsigned char iv[16];
    memset(iv, 0, 16);
    memcpy(iv+4, nonce, 12); /* counter 0 at start? */
    t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, chacha, NULL, key, iv);
        EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)N);
        EVP_EncryptFinal_ex(ctx, ct + outlen, &tmplen);
    }
    t1 = now();
    printf("evp chacha20: %.4f s/op\n", (t1-t0)/reps);

    /* direct ChaCha20_ctr32 */
    unsigned int kwords[8], cwords[4];
    memcpy(kwords, key, 32);
    cwords[0] = 1;
    memcpy(&cwords[1], nonce, 12);
    t0 = now();
    for (int i = 0; i < reps; i++) {
        cwords[0] = 1;
        ChaCha20_ctr32(ct, pt, N, kwords, cwords);
    }
    t1 = now();
    printf("ChaCha20_ctr32: %.4f s/op\n", (t1-t0)/reps);

    /* poly1305 over ct */
    size_t ctxsz = Poly1305_ctx_size();
    void *pctx = malloc(ctxsz);
    unsigned char pkey[32];
    memset(pkey, 1, 32);
    t0 = now();
    for (int i = 0; i < reps; i++) {
        Poly1305_Init(pctx, pkey);
        Poly1305_Update(pctx, ct, N);
        Poly1305_Final(pctx, tag);
    }
    t1 = now();
    printf("Poly1305: %.4f s/op\n", (t1-t0)/reps);

    /* combined direct: chacha then poly, no extra copies */
    t0 = now();
    for (int i = 0; i < reps; i++) {
        unsigned char block0[64];
        unsigned char zeros[64] = {0};
        cwords[0] = 0;
        ChaCha20_ctr32(block0, zeros, 64, kwords, cwords);
        cwords[0] = 1;
        ChaCha20_ctr32(ct, pt, N, kwords, cwords);
        Poly1305_Init(pctx, block0);
        /* aad */
        Poly1305_Update(pctx, aad, 32);
        Poly1305_Update(pctx, ct, N);
        unsigned char lens[16];
        /* little endian lengths */
        unsigned long long la = 32, lp = N;
        memcpy(lens, &la, 8);
        memcpy(lens+8, &lp, 8);
        Poly1305_Update(pctx, lens, 16);
        Poly1305_Final(pctx, tag);
    }
    t1 = now();
    printf("direct aead: %.4f s/op tag0=%02x\n", (t1-t0)/reps, tag[0]);

    return 0;
}
EOF
