{"command":"cat > build/bench_raw.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);
size_t Poly1305_ctx_size(void);

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static unsigned char *g_pt, *g_ct;
static unsigned int g_key[8];
static unsigned int g_nonce[3];
static size_t g_N;
static int g_threads;

typedef struct { size_t start; size_t len; unsigned int counter; } Job;

static void *worker(void *arg) {
    Job *j = arg;
    unsigned int counter[4] = {j->counter, g_nonce[0], g_nonce[1], g_nonce[2]};
    ChaCha20_ctr32(g_ct + j->start, g_pt + j->start, j->len, g_key, counter);
    return NULL;
}

static void parallel_chacha(int nthreads) {
    /* split into nthreads chunks, 64-byte aligned except last */
    pthread_t th[16];
    Job jobs[16];
    size_t chunk = (g_N / nthreads) & ~((size_t)63);
    size_t off = 0;
    unsigned int ctr = 1;
    for (int i = 0; i < nthreads; i++) {
        size_t len = (i == nthreads - 1) ? (g_N - off) : chunk;
        jobs[i].start = off;
        jobs[i].len = len;
        jobs[i].counter = ctr;
        ctr += (unsigned int)((len + 63) / 64);
        off += len;
        pthread_create(&th[i], NULL, worker, &jobs[i]);
    }
    for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
}

int main() {
    size_t N = 40000u * 1024u;
    g_N = N;
    g_pt = malloc(N);
    g_ct = malloc(N);
    unsigned char keyb[32], nonce[12], aad[32], tag[16];
    FILE *f = fopen("/dev/urandom", "rb");
    fread(g_pt, 1, N, f);
    fread(keyb, 1, 32, f);
    fread(nonce, 1, 12, f);
    fread(aad, 1, 32, f);
    fclose(f);
    memcpy(g_key, keyb, 32);
    memcpy(g_nonce, nonce, 12);

    int reps = 5;
    double t0 = now();
    for (int i = 0; i < reps; i++) {
        unsigned int counter[4] = {1, g_nonce[0], g_nonce[1], g_nonce[2]};
        ChaCha20_ctr32(g_ct, g_pt, N, g_key, counter);
    }
    printf("serial chacha %.4f\n", (now()-t0)/reps);

    for (int nt = 2; nt <= 8; nt += 2) {
        t0 = now();
        for (int i = 0; i < reps; i++) parallel_chacha(nt);
        printf("parallel %d %.4f\n", nt, (now()-t0)/reps);
    }

    size_t ctxsz = Poly1305_ctx_size();
    void *pctx = malloc(ctxsz);
    unsigned char pkey[32];
    memset(pkey, 7, 32);
    t0 = now();
    for (int i = 0; i < reps; i++) {
        Poly1305_Init(pctx, pkey);
        Poly1305_Update(pctx, g_ct, N);
        Poly1305_Final(pctx, tag);
    }
    printf("poly1305 %.4f\n", (now()-t0)/reps);

    /* combined serial */
    t0 = now();
    for (int i = 0; i < reps; i++) {
        unsigned char block0[64] = {0};
        unsigned char zeros[64] = {0};
        unsigned int c0[4] = {0, g_nonce[0], g_nonce[1], g_nonce[2]};
        ChaCha20_ctr32(block0, zeros, 64, g_key, c0);
        unsigned int c1[4] = {1, g_nonce[0], g_nonce[1], g_nonce[2]};
        ChaCha20_ctr32(g_ct, g_pt, N, g_key, c1);
        Poly1305_Init(pctx, block0);
        Poly1305_Update(pctx, aad, 32);
        Poly1305_Update(pctx, g_ct, N);
        unsigned long long lens[2] = {32, N};
        Poly1305_Update(pctx, (unsigned char*)lens, 16);
        Poly1305_Final(pctx, tag);
    }
    printf("serial aead %.4f tag0=%02x\n", (now()-t0)/reps, tag[0]);

    /* parallel chacha + serial poly */
    t0 = now();
    for (int i = 0; i < reps; i++) {
        unsigned char block0[64] = {0};
        unsigned char zeros[64] = {0};
        unsigned int c0[4] = {0, g_nonce[0], g_nonce[1], g_nonce[2]};
        ChaCha20_ctr32(block0, zeros, 64, g_key, c0);
        parallel_chacha(6);
        Poly1305_Init(pctx, block0);
        Poly1305_Update(pctx, aad, 32);
        Poly1305_Update(pctx, g_ct, N);
        unsigned long long lens[2] = {32, N};
        Poly1305_Update(pctx, (unsigned char*)lens, 16);
        Poly1305_Final(pctx, tag);
    }
    printf("par6 aead %.4f\n", (now()-t0)/reps);
    return 0;
}
EOF
