{"command":"cat > build/poly_avx2.c << 'EOF'
/*
 * Poly1305 AVX2, Donna-style 26-bit limbs, 4-way interleaved blocks.
 * Verify against OpenSSL Poly1305.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <immintrin.h>

void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);
size_t Poly1305_ctx_size(void);

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

/* scalar reference (26-bit) for correctness of one block, then AVX2 */
typedef struct {
    uint32_t r[5];
    uint32_t h[5];
    uint32_t pad[4];
    unsigned char buf[16];
    size_t buf_used;
    int final_done;
} PState;

static void p_init(PState *st, const unsigned char key[32]) {
    memset(st, 0, sizeof(*st));
    uint32_t t0 = (uint32_t)key[0] | ((uint32_t)key[1]<<8) | ((uint32_t)key[2]<<16) | ((uint32_t)key[3]<<24);
    uint32_t t1 = (uint32_t)key[4] | ((uint32_t)key[5]<<8) | ((uint32_t)key[6]<<16) | ((uint32_t)key[7]<<24);
    uint32_t t2 = (uint32_t)key[8] | ((uint32_t)key[9]<<8) | ((uint32_t)key[10]<<16) | ((uint32_t)key[11]<<24);
    uint32_t t3 = (uint32_t)key[12] | ((uint32_t)key[13]<<8) | ((uint32_t)key[14]<<16) | ((uint32_t)key[15]<<24);
    /* clamp */
    st->r[0] = t0 & 0x3ffffff;
    st->r[1] = ((t0 >> 26) | (t1 << 6)) & 0x3ffff03;
    st->r[2] = ((t1 >> 20) | (t2 << 12)) & 0x3ffc0ff;
    st->r[3] = ((t2 >> 14) | (t3 << 18)) & 0x3f03fff;
    st->r[4] = (t3 >> 8) & 0x00fffff;
    st->pad[0] = (uint32_t)key[16] | ((uint32_t)key[17]<<8) | ((uint32_t)key[18]<<16) | ((uint32_t)key[19]<<24);
    st->pad[1] = (uint32_t)key[20] | ((uint32_t)key[21]<<8) | ((uint32_t)key[22]<<16) | ((uint32_t)key[23]<<24);
    st->pad[2] = (uint32_t)key[24] | ((uint32_t)key[25]<<8) | ((uint32_t)key[26]<<16) | ((uint32_t)key[27]<<24);
    st->pad[3] = (uint32_t)key[28] | ((uint32_t)key[29]<<8) | ((uint32_t)key[30]<<16) | ((uint32_t)key[31]<<24);
}

static void blocks_scalar(PState *st, const unsigned char *m, size_t bytes, uint32_t hibit) {
    uint32_t r0=st->r[0], r1=st->r[1], r2=st->r[2], r3=st->r[3], r4=st->r[4];
    uint32_t s1=r1*5, s2=r2*5, s3=r3*5, s4=r4*5;
    uint32_t h0=st->h[0], h1=st->h[1], h2=st->h[2], h3=st->h[3], h4=st->h[4];
    while (bytes >= 16) {
        uint32_t t0 = (uint32_t)m[0] | ((uint32_t)m[1]<<8) | ((uint32_t)m[2]<<16) | ((uint32_t)m[3]<<24);
        uint32_t t1 = (uint32_t)m[4] | ((uint32_t)m[5]<<8) | ((uint32_t)m[6]<<16) | ((uint32_t)m[7]<<24);
        uint32_t t2 = (uint32_t)m[8] | ((uint32_t)m[9]<<8) | ((uint32_t)m[10]<<16) | ((uint32_t)m[11]<<24);
        uint32_t t3 = (uint32_t)m[12] | ((uint32_t)m[13]<<8) | ((uint32_t)m[14]<<16) | ((uint32_t)m[15]<<24);
        h0 += t0 & 0x3ffffff;
        h1 += ((t0>>26)|(t1<<6)) & 0x3ffffff;
        h2 += ((t1>>20)|(t2<<12)) & 0x3ffffff;
        h3 += ((t2>>14)|(t3<<18)) & 0x3ffffff;
        h4 += (t3>>8) | hibit;

