/* AVX2: multiply-add 4 message limbs by r^k and accumulate into 5x u64 vectors stored as 2x __m256i? 
 * Simpler: each limb product is u32*u32 -> u64. 4 lanes of u64 fit in __m256i.
 * h limbs are scalar (only one accumulator), message limbs are 4-wide.
 *
 * d0 = h0*r4_0 + h1*s4_4 + ...   +  m0_0*r4_0 + m0_1*s4_4 + ...
 *    + m1_0*r3_0 + ...
 *    + m2_0*r2_0 + ...
 *    + m3_0*r_0  + ...
 *
 * We'll compute 4-wide products of message limbs and horizontal-sum? No: each lane is an independent
 * contribution that must be SUMMED (they're all added into the same accumulator), not kept separate.
 * So after 4-wide mul we need a horizontal add of the 4 u64 lanes. That's fine and still faster
 * than scalar if we pipeline loads... actually horizontal add of 4 independent products that all
 * sum into one accumulator doesn't give algorithmic speedup vs scalar unless we use precomputed
 * powers and the muls are independent (ILP). AVX2 gives us 4 independent 32x32->64 in one instruction
 * if we use vpmuludq on even lanes. A __m256i holds 4 u64, vpmuludq multiplies 32-bit lanes 0,2,4,6.
 * So one vpmuludq does 4 multiplies. We need 25 multiplies per block * 4 blocks = 100, vs scalar 25*4.
 * With AVX we do 100/4 = 25 vpmuludq plus adds. Similar instruction count to 100 scalar muls but
 * scalar mul is also 1/cycle throughput on port... 32x32->64 mul throughput on Skylake is 1/cycle
 * for mulx? vpmuludq throughput is 1/cycle (p0) on Skylake? Actually vpmuludq is 1 per cycle on p0.
 * So 4x more multiplies per instruction => ~4x. Good.
 */

static inline uint64_t hsum256(__m256i v) {
    __m128i lo = _mm256_castsi256_si128(v);
    __m128i hi = _mm256_extracti128_si256(v, 1);
    __m128i s = _mm_add_epi64(lo, hi);
    return (uint64_t)_mm_cvtsi128_si64(s) + (uint64_t)_mm_extract_epi64(s, 1);
}

