    memcpy(R[0], st->r4, 20);
    memcpy(R[1], st->r3, 20);
    memcpy(R[2], st->r2, 20);
    memcpy(R[3], st->r, 20);
    for (int i = 0; i < 4; i++) {
        S4[i][1] = R[i][1]*5;
        S4[i][2] = R[i][2]*5;
        S4[i][3] = R[i][3]*5;
        S4[i][4] = R[i][4]*5;
    }

    /* Broadcast coefficients as u32 in low half of each u64 lane, 4 blocks.
       Lane order: 0 oldest .. 3 newest. vpmuludq multiplies the low 32 bits of each 64-bit lane. */
#define COEFF(arr, limb) _mm256_set_epi64x(arr[3][limb], arr[2][limb], arr[1][limb], arr[0][limb])
    __m256i r0 = COEFF(R, 0);
    __m256i r1 = COEFF(R, 1);
    __m256i r2 = COEFF(R, 2);
    __m256i r3 = COEFF(R, 3);
    __m256i r4 = COEFF(R, 4);
    __m256i s1 = COEFF(S4, 1);
    __m256i s2 = COEFF(S4, 2);
    __m256i s3 = COEFF(S4, 3);
    __m256i s4 = COEFF(S4, 4);
#undef COEFF

    uint32_t h0=st->h[0], h1=st->h[1], h2=st->h[2], h3=st->h[3], h4=st->h[4];
    const __m256i mask26 = _mm256_set1_epi32(0x3ffffff);

    while (bytes >= 64) {
        uint32_t ml0[4], ml1[4], ml2[4], ml3[4], ml4[4];
        for (int b = 0; b < 4; b++) {
            const unsigned char *p = m + b*16;
            uint32_t t0 = *(const uint32_t*)(p);
            uint32_t t1 = *(const uint32_t*)(p+4);
            uint32_t t2 = *(const uint32_t*)(p+8);
            uint32_t t3 = *(const uint32_t*)(p+12);
            ml0[b] = t0 & 0x3ffffff;
            ml1[b] = ((t0>>26)|(t1<<6)) & 0x3ffffff;
            ml2[b] = ((t1>>20)|(t2<<12)) & 0x3ffffff;
            ml3[b] = ((t2>>14)|(t3<<18)) & 0x3ffffff;
            ml4[b] = (t3>>8) | hibit;
        }
        ml0[0] += h0; ml1[0] += h1; ml2[0] += h2; ml3[0] += h3; ml4[0] += h4;

        __m256i m0 = _mm256_set_epi64x(ml0[3], ml0[2], ml0[1], ml0[0]);
        __m256i m1 = _mm256_set_epi64x(ml1[3], ml1[2], ml1[1], ml1[0]);
        __m256i m2 = _mm256_set_epi64x(ml2[3], ml2[2], ml2[1], ml2[0]);
        __m256i m3 = _mm256_set_epi64x(ml3[3], ml3[2], ml3[1], ml3[0]);
        __m256i m4 = _mm256_set_epi64x(ml4[3], ml4[2], ml4[1], ml4[0]);

        __m256i d0v = _mm256_mul_epu32(m0, r0);
        d0v = _mm256_add_epi64(d0v, _mm256_mul_epu32(m1, s4));
        d0v = _mm256_add_epi64(d0v, _mm256_mul_epu32(m2, s3));
        d0v = _mm256_add_epi64(d0v, _mm256_mul_epu32(m3, s2));
        d0v = _mm256_add_epi64(d0v, _mm256_mul_epu32(m4, s1));

        __m256i d1v = _mm256_mul_epu32(m0, r1);
        d1v = _mm256_add_epi64(d1v, _mm256_mul_epu32(m1, r0));
        d1v = _mm256_add_epi64(d1v, _mm256_mul_epu32(m2, s4));
        d1v = _mm256_add_epi64(d1v, _mm256_mul_epu32(m3, s3));
        d1v = _mm256_add_epi64(d1v, _mm256_mul_epu32(m4, s2));

        __m256i d2v = _mm256_mul_epu32(m0, r2);
        d2v = _mm256_add_epi64(d2v, _mm256_mul_epu32(m1, r1));
        d2v = _mm256_add_epi64(d2v, _mm256_mul_epu32(m2, r0));
        d2v = _mm256_add_epi64(d2v, _mm256_mul_epu32(m3, s4));
        d2v = _mm256_add_epi64(d2v, _mm256_mul_epu32(m4, s3));

        __m256i d3v = _mm256_mul_epu32(m0, r3);
        d3v = _mm256_add_epi64(d3v, _mm256_mul_epu32(m1, r2));
        d3v = _mm256_add_epi64(d3v, _mm256_mul_epu32(m2, r1));
        d3v = _mm256_add_epi64(d3v, _mm256_mul_epu32(m3, r0));
        d3v = _mm256_add_epi64(d3v, _mm256_mul_epu32(m4, s4));

        __m256i d4v = _mm256_mul_epu32(m0, r4);
        d4v = _mm256_add_epi64(d4v, _mm256_mul_epu32(m1, r3));
        d4v = _mm256_add_epi64(d4v, _mm256_mul_epu32(m2, r2));
        d4v = _mm256_add_epi64(d4v, _mm256_mul_epu32(m3, r1));
        d4v = _mm256_add_epi64(d4v, _mm256_mul_epu32(m4, r0));

        uint64_t d0 = hsum256(d0v);
        uint64_t d1 = hsum256(d1v);
        uint64_t d2 = hsum256(d2v);
        uint64_t d3 = hsum256(d3v);
        uint64_t d4 = hsum256(d4v);

        uint64_t c;
        c = d0 >> 26; h0 = (uint32_t)d0 & 0x3ffffff; d1 += c;
        c = d1 >> 26; h1 = (uint32_t)d1 & 0x3ffffff; d2 += c;
        c = d2 >> 26; h2 = (uint32_t)d2 & 0x3ffffff; d3 += c;
        c = d3 >> 26; h3 = (uint32_t)d3 & 0x3ffffff; d4 += c;
        c = d4 >> 26; h4 = (uint32_t)d4 & 0x3ffffff; h0 += (uint32_t)c * 5;
        c = h0 >> 26; h0 &= 0x3ffffff; h1 += (uint32_t)c;

        m += 64; bytes -= 64;
    }
    st->h[0]=h0; st->h[1]=h1; st->h[2]=h2; st->h[3]=h3; st->h[4]=h4;
    if (bytes) blocks_scalar(st, m, bytes, hibit);
    (void)mask26;
}

static void p_update(PState *st, const unsigned char *m, size_t len, int avx) {
    if (st->buf_used) {
        size_t need = 16 - st->buf_used;
        if (len < need) { memcpy(st->buf + st->buf_used, m, len); st->buf_used += len; return; }
        memcpy(st->buf + st->buf_used, m, need);
        blocks_scalar(st, st->buf, 16, 1u<<24);
        st->buf_used = 0;
        m += need; len -= need;
    }
    size_t n = len & ~((size_t)15);
    if (n) {
        if (avx) blocks_avx2_real(st, m, n);
        else blocks_scalar(st, m, n, 1u<<24);
    }
    if (len & 15) {
        memcpy(st->buf, m + (len & ~15u), len & 15);
        st->buf_used = len & 15;
    }
}

static void p_final(PState *st, unsigned char mac[16]) {
    if (st->buf_used) {
        st->buf[st->buf_used] = 1;
        for (size_t i = st->buf_used+1; i < 16; i++) st->buf[i] = 0;
        blocks_scalar(st, st->buf, 16, 0);
    }
    uint32_t h0=st->h[0], h1=st->h[1], h2=st->h[2], h3=st->h[3], h4=st->h[4];
    uint32_t c;
    c = h1 >> 26; h1 &= 0x3ffffff; h2 += c;
    c = h2 >> 26; h2 &= 0x3ffffff; h3 += c;
    c = h3 >> 26; h3 &= 0x3ffffff; h4 += c;
    c = h4 >> 26; h4 &= 0x3ffffff; h0 += c * 5;
    c = h0 >> 26; h0 &= 0x3ffffff; h1 += c;

    uint32_t g0 = h0 + 5; c = g0 >> 26; g0 &= 0x3ffffff;
    uint32_t g1 = h1 + c; c = g1 >> 26; g1 &= 0x3ffffff;
    uint32_t g2 = h2 + c; c = g2 >> 26; g2 &= 0x3ffffff;
    uint32_t g3 = h3 + c; c = g3 >> 26; g3 &= 0x3ffffff;
    uint32_t g4 = h4 + c - (1u<<26);
    uint32_t mask = (g4 >> 31) - 1u;
    g0 &= mask; g1 &= mask; g2 &= mask; g3 &= mask; g4 &= mask;
    mask = ~mask;
    h0 = (h0 & mask) | g0;
    h1 = (h1 & mask) | g1;
    h2 = (h2 & mask) | g2;
    h3 = (h3 & mask) | g3;
    h4 = (h4 & mask) | g4;

    uint64_t h_lo = (uint64_t)h0 | ((uint64_t)h1 << 26) | (((uint64_t)h2 & 0xfff) << 52);
    uint64_t h_hi = ((uint64_t)h2 >> 12) | ((uint64_t)h3 << 14) | ((uint64_t)h4 << 40);
    uint64_t p_lo = (uint64_t)st->pad[0] | ((uint64_t)st->pad[1] << 32);
    uint64_t p_hi = (uint64_t)st->pad[2] | ((uint64_t)st->pad[3] << 32);
    uint64_t s_lo = h_lo + p_lo;
    uint64_t s_hi = h_hi + p_hi + (s_lo < h_lo);
    memcpy(mac, &s_lo, 8);
    memcpy(mac+8, &s_hi, 8);
}

int main() {
    size_t ctxsz = Poly1305_ctx_size();
    void *octx = malloc(ctxsz);
    unsigned char key[32];
    for (int i = 0; i < 32; i++) key[i] = (unsigned char)(i*7+3);
    size_t N = 40*1024*1024;
    unsigned char *msg = malloc(N+128);
    FILE *f = fopen("/dev/urandom","rb"); fread(msg,1,N,f); fclose(f);

    size_t lens[] = {0,1,15,16,17,31,32,63,64,65,100,128,1000,4096,100000, N};
    for (size_t li = 0; li < sizeof(lens)/sizeof(lens[0]); li++) {
        unsigned char t1[16], t2[16];
        Poly1305_Init(octx, key);
        Poly1305_Update(octx, msg, lens[li]);
        Poly1305_Final(octx, t1);
        PState st; p_init(&st, key);
        p_update(&st, msg, lens[li], 1);
        p_final(&st, t2);
        if (memcmp(t1,t2,16)) {
            printf("FAIL len %zu\n", lens[li]);
            return 1;
        }
    }
    printf("avx match OK\n");

    unsigned char tag[16];
    int reps = 5;
    double t0 = now();
    for (int i=0;i<reps;i++) {
        Poly1305_Init(octx, key); Poly1305_Update(octx, msg, N); Poly1305_Final(octx, tag);
    }
    printf("openssl %.4f\n", (now()-t0)/reps);
    t0 = now();
    for (int i=0;i<reps;i++) {
        PState st; p_init(&st, key); p_update(&st, msg, N, 1); p_final(&st, tag);
    }
    printf("avx2 %.4f\n", (now()-t0)/reps);
    return 0;
}
