#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <stdlib.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);
size_t Poly1305_ctx_size(void);

#define NTHREADS 6

typedef struct {
    unsigned char *out;
    const unsigned char *in;
    size_t len;
    unsigned int counter;
    unsigned int nonce[3];
    unsigned int key[8];
} Job;

static void *worker(void *arg) {
    Job *j = (Job *)arg;
    unsigned int ctr[4] = {j->counter, j->nonce[0], j->nonce[1], j->nonce[2]};
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, ctr);
    return NULL;
}

static void parallel_chacha(unsigned char *out, const unsigned char *in, size_t n,
                            const unsigned int key[8], const unsigned int nonce[3],
                            unsigned int counter0) {
    if (n < 1024 * 1024 || NTHREADS <= 1) {
        unsigned int ctr[4] = {counter0, nonce[0], nonce[1], nonce[2]};
        ChaCha20_ctr32(out, in, n, key, ctr);
        return;
    }
    pthread_t th[NTHREADS];
    Job jobs[NTHREADS];
    size_t chunk = (n / NTHREADS) & ~((size_t)63);
    if (chunk == 0) chunk = 64;
    size_t off = 0;
    unsigned int ctr = counter0;
    int spawned = 0;
    for (int i = 0; i < NTHREADS; i++) {
        size_t len = (i == NTHREADS - 1) ? (n - off) : chunk;
        if (off >= n) break;
        if (len > n - off) len = n - off;
        jobs[i].out = out + off;
        jobs[i].in = in + off;
        jobs[i].len = len;
        jobs[i].counter = ctr;
        jobs[i].nonce[0] = nonce[0];
        jobs[i].nonce[1] = nonce[1];
        jobs[i].nonce[2] = nonce[2];
        memcpy(jobs[i].key, key, 32);
        ctr += (unsigned int)((len + 63) / 64);
        off += len;
        pthread_create(&th[i], NULL, worker, &jobs[i]);
        spawned++;
    }
    for (int i = 0; i < spawned; i++) pthread_join(th[i], NULL);
}

static PyObject *encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    int has_aad = 0;
    if (!PyArg_ParseTuple(args, "y*y*y*|y*", &key, &nonce, &pt, &aad)) {
        /* try with None aad: parse 3 then optional */
        PyErr_Clear();
        if (!PyArg_ParseTuple(args, "y*y*y*O", &key, &nonce, &pt, &self)) {
            return NULL;
        }
    }
    /* Simpler rewrite below not used */
    return NULL;
}

/* cleaner implementation */
static PyObject *py_encrypt(PyObject *self, PyObject *args) {
    PyObject *key_o, *nonce_o, *pt_o, *aad_o = Py_None;
    if (!PyArg_ParseTuple(args, "OOO|O", &key_o, &nonce_o, &pt_o, &aad_o))
        return NULL;

    Py_buffer key, nonce, pt, aad;
    memset(&aad, 0, sizeof(aad));
    if (PyObject_GetBuffer(key_o, &key, PyBUF_SIMPLE) < 0) return NULL;
    if (PyObject_GetBuffer(nonce_o, &nonce, PyBUF_SIMPLE) < 0) { PyBuffer_Release(&key); return NULL; }
    if (PyObject_GetBuffer(pt_o, &pt, PyBUF_SIMPLE) < 0) { PyBuffer_Release(&nonce); PyBuffer_Release(&key); return NULL; }
    int have_aad = 0;
    if (aad_o != Py_None && aad_o != NULL) {
        if (PyObject_GetBuffer(aad_o, &aad, PyBUF_SIMPLE) < 0) {
            PyBuffer_Release(&pt); PyBuffer_Release(&nonce); PyBuffer_Release(&key);
            return NULL;
        }
        have_aad = 1;
    }

    if (key.len != 32 || nonce.len != 12) {
        PyErr_SetString(PyExc_ValueError, "bad key/nonce size");
        goto fail;
    }

    PyObject *ct_o = PyBytes_FromStringAndSize(NULL, pt.len);
    if (!ct_o) goto fail;
    unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_o);

    unsigned int kwords[8];
    unsigned int nwords[3];
    memcpy(kwords, key.buf, 32);
    memcpy(nwords, nonce.buf, 12);

    /* one-time key */
    unsigned char block0[64];
    unsigned char zeros[64] = {0};
    unsigned int c0[4] = {0, nwords[0], nwords[1], nwords[2]};
    ChaCha20_ctr32(block0, zeros, 64, kwords, c0);

    if (pt.len)
        parallel_chacha(ct, (const unsigned char *)pt.buf, (size_t)pt.len, kwords, nwords, 1);

    size_t ctxsz = Poly1305_ctx_size();
    void *pctx = PyMem_Malloc(ctxsz);
    if (!pctx) { Py_DECREF(ct_o); PyErr_NoMemory(); goto fail; }
    Poly1305_Init(pctx, block0);
    size_t aad_len = have_aad ? (size_t)aad.len : 0;
    const unsigned char *aad_buf = have_aad ? (const unsigned char *)aad.buf : NULL;
    if (aad_len) {
        Poly1305_Update(pctx, aad_buf, aad_len);
        size_t pad = (16 - (aad_len & 15)) & 15;
        if (pad) {
            unsigned char z[16] = {0};
            Poly1305_Update(pctx, z, pad);
        }
    }
    if (pt.len) {
        Poly1305_Update(pctx, ct, (size_t)pt.len);
        size_t pad = (16 - ((size_t)pt.len & 15)) & 15;
        if (pad) {
            unsigned char z[16] = {0};
            Poly1305_Update(pctx, z, pad);
        }
    }
    unsigned long long lens[2] = {aad_len, (unsigned long long)pt.len};
    Poly1305_Update(pctx, (unsigned char *)lens, 16);
    unsigned char tag[16];
    Poly1305_Final(pctx, tag);
    PyMem_Free(pctx);

    PyObject *tag_o = PyBytes_FromStringAndSize((char *)tag, 16);
    if (!tag_o) { Py_DECREF(ct_o); goto fail; }

    PyObject *res = PyTuple_New(2);
    PyTuple_SET_ITEM(res, 0, ct_o);
    PyTuple_SET_ITEM(res, 1, tag_o);

    PyBuffer_Release(&pt);
    PyBuffer_Release(&nonce);
    PyBuffer_Release(&key);
    if (have_aad) PyBuffer_Release(&aad);
    return res;

fail:
    PyBuffer_Release(&pt);
    PyBuffer_Release(&nonce);
    PyBuffer_Release(&key);
    if (have_aad) PyBuffer_Release(&aad);
    return NULL;
}

static PyMethodDef methods[] = {
    {"encrypt", py_encrypt, METH_VARARGS, "ChaCha20-Poly1305 encrypt"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "fastchacha", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_fastchacha(void) {
    return PyModule_Create(&moduledef);
}
