    printf("nettle chacha32 %.4f\n", (now()-t0)/reps);

    int nthreads=6;
    t0=now();
    for(int r=0;r<reps;r++){
        pthread_t th[8];
        Job jobs[8];
        size_t chunk=(N/nthreads)&~63ull;
