/* 4-way AVX2 ChaCha20, compare to OpenSSL ChaCha20_ctr32 */
#include <immintrin.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

static inline __m256i rotl32(__m256i x, int n) {
    return _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32-n));
}

static inline void quarter(__m256i *a, __m256i *b, __m256i *c, __m256i *d) {
    *a = _mm256_add_epi32(*a, *b); *d = _mm256_xor_si256(*d, *a); *d = rotl32(*d, 16);
    *c = _mm256_add_epi32(*c, *d); *b = _mm256_xor_si256(*b, *c); *b = rotl32(*b, 12);
    *a = _mm256_add_epi32(*a, *b); *d = _mm256_xor_si256(*d, *a); *d = rotl32(*d, 8);
    *c = _mm256_add_epi32(*c, *d); *b = _mm256_xor_si256(*b, *c); *b = rotl32(*b, 7);
}

/* encrypt len bytes, len multiple of 256 (4 blocks) for the fast path, remainder scalar via openssl? we'll handle remainder with 1-block avx (waste) or simple */
static void chacha20_avx2_4x(unsigned char *out, const unsigned char *in, size_t len,
                             const unsigned int key[8], unsigned int counter, const unsigned int nonce[3]) {
    const __m256i one = _mm256_set1_epi32(1);
    /* constants */
    const uint32_t c0=0x61707865, c1=0x3320646e, c2=0x79622d32, c3=0x6b206574;
    while (len >= 256) {
        __m256i x0 = _mm256_set1_epi32(c0);
        __m256i x1 = _mm256_set1_epi32(c1);
        __m256i x2 = _mm256_set1_epi32(c2);
        __m256i x3 = _mm256_set1_epi32(c3);
        __m256i x4 = _mm256_set1_epi32(key[0]);
        __m256i x5 = _mm256_set1_epi32(key[1]);
        __m256i x6 = _mm256_set1_epi32(key[2]);
        __m256i x7 = _mm256_set1_epi32(key[3]);
        __m256i x8 = _mm256_set1_epi32(key[4]);
        __m256i x9 = _mm256_set1_epi32(key[5]);
        __m256i x10= _mm256_set1_epi32(key[6]);
        __m256i x11= _mm256_set1_epi32(key[7]);
        __m256i x12= _mm256_set_epi32(counter+3, counter+2, counter+1, counter);
        __m256i x13= _mm256_set1_epi32(nonce[0]);
        __m256i x14= _mm256_set1_epi32(nonce[1]);
        __m256i x15= _mm256_set1_epi32(nonce[2]);

        __m256i s0=x0,s1=x1,s2=x2,s3=x3,s4=x4,s5=x5,s6=x6,s7=x7;
        __m256i s8=x8,s9=x9,s10=x10,s11=x11,s12=x12,s13=x13,s14=x14,s15=x15;

        for (int i=0;i<10;i++) {
            quarter(&x0,&x4,&x8,&x12);
            quarter(&x1,&x5,&x9,&x13);
            quarter(&x2,&x6,&x10,&x14);
            quarter(&x3,&x7,&x11,&x15);
            quarter(&x0,&x5,&x10,&x15);
            quarter(&x1,&x6,&x11,&x12);
            quarter(&x2,&x7,&x8,&x13);
            quarter(&x3,&x4,&x9,&x14);
        }
        x0=_mm256_add_epi32(x0,s0); x1=_mm256_add_epi32(x1,s1);
        x2=_mm256_add_epi32(x2,s2); x3=_mm256_add_epi32(x3,s3);
        x4=_mm256_add_epi32(x4,s4); x5=_mm256_add_epi32(x5,s5);
        x6=_mm256_add_epi32(x6,s6); x7=_mm256_add_epi32(x7,s7);
        x8=_mm256_add_epi32(x8,s8); x9=_mm256_add_epi32(x9,s9);
        x10=_mm256_add_epi32(x10,s10); x11=_mm256_add_epi32(x11,s11);
        x12=_mm256_add_epi32(x12,s12); x13=_mm256_add_epi32(x13,s13);
        x14=_mm256_add_epi32(x14,s14); x15=_mm256_add_epi32(x15,s15);

        /* transpose 4 blocks of 16 words into memory order.
           each xi has lanes [b0,b1,b2,b3] of word i.
           We want for block b: words 0..15 contiguous.
           Store via extract. */
        uint32_t tmp[4][16];
        #define STORE(xi, idx) do { \
            alignas(32) uint32_t b[4]; \
            _mm256_store_si256((__m256i*)b, xi); \
            tmp[0][idx]=b[0]; tmp[1][idx]=b[1]; tmp[2][idx]=b[2]; tmp[3][idx]=b[3]; \
        } while(0)
        STORE(x0,0); STORE(x1,1); STORE(x2,2); STORE(x3,3);
        STORE(x4,4); STORE(x5,5); STORE(x6,6); STORE(x7,7);
        STORE(x8,8); STORE(x9,9); STORE(x10,10); STORE(x11,11);
        STORE(x12,12); STORE(x13,13); STORE(x14,14); STORE(x15,15);
        #undef STORE
        for (int b=0;b<4;b++) {
            const uint32_t *ks = tmp[b];
            const uint32_t *src = (const uint32_t*)(in + b*64);
            uint32_t *dst = (uint32_t*)(out + b*64);
            for (int w=0;w<16;w++) dst[w] = src[w] ^ ks[w];
        }
        in += 256; out += 256; len -= 256; counter += 4;
    }
    if (len) {
        unsigned int ctr[4] = {counter, nonce[0], nonce[1], nonce[2]};
        /* key already */
        /* use openssl for tail by reconstructing key array - caller passes key */
        /* We don't have key as uint array separate if we consumed... we have key param */
        ChaCha20_ctr32(out, in, len, key, ctr);
    }
    (void)one;
}

int main(){
    size_t N=40*1024*1024;
    N &= ~255ull;
    unsigned char *pt=malloc(N), *ct1=malloc(N), *ct2=malloc(N);
    unsigned int key[8];
    unsigned int nonce[3];
    FILE *f=fopen("/dev/urandom","rb");
    fread(pt,1,N,f); fread(key,1,32,f); fread(nonce,1,12,f); fclose(f);
    unsigned int ctr[4]={1, nonce[0], nonce[1], nonce[2]};
    ChaCha20_ctr32(ct1, pt, N, key, ctr);
    chacha20_avx2_4x(ct2, pt, N, key, 1, nonce);
    if (memcmp(ct1, ct2, N)!=0) {
        printf("MISMATCH\n");
        for (size_t i=0;i<N;i++) if (ct1[i]!=ct2[i]) { printf("at %zu %02x %02x\n", i, ct1[i], ct2[i]); break; }
        return 1;
    }
    printf("match OK\n");
    int reps=5;
    double t0=now();
    for(int i=0;i<reps;i++){
        unsigned int c[4]={1, nonce[0], nonce[1], nonce[2]};
        ChaCha20_ctr32(ct1, pt, N, key, c);
    }
    printf("openssl %.4f\n", (now()-t0)/reps);
    t0=now();
    for(int i=0;i<reps;i++) chacha20_avx2_4x(ct2, pt, N, key, 1, nonce);
    printf("avx2 4x %.4f\n", (now()-t0)/reps);
    return 0;
}
