static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

/* 130-bit little-endian add/mul mod 2^130-5 using 5x26 is overkill; use 3x64 with __int128 */
typedef unsigned __int128 u128;

static void add130(uint64_t *a, const uint64_t *b) {
    /* a,b are 3 limbs, a[2] and b[2] only low 2 bits meaningful, value < 2^130 */
    u128 s0 = (u128)a[0] + b[0];
    u128 s1 = (u128)a[1] + b[1] + (uint64_t)(s0 >> 64);
    u128 s2 = (u128)a[2] + b[2] + (uint64_t)(s1 >> 64);
    a[0] = (uint64_t)s0;
    a[1] = (uint64_t)s1;
    a[2] = (uint64_t)s2;
    /* reduce if >= 2^130 */
    if (a[2] >= 4) {
        uint64_t hi = a[2] >> 2; /* multiple of 2^130 */
        a[2] &= 3;
        u128 t = (u128)a[0] + hi * 5;
        a[0] = (uint64_t)t;
        t = (u128)a[1] + (uint64_t)(t >> 64);
        a[1] = (uint64_t)t;
        a[2] += (uint64_t)(t >> 64);
        if (a[2] >= 4) {
            hi = a[2] >> 2; a[2] &= 3;
            t = (u128)a[0] + hi * 5;
            a[0]=(uint64_t)t;
            t=(u128)a[1]+(uint64_t)(t>>64);
            a[1]=(uint64_t)t;
            a[2]+=(uint64_t)(t>>64);
        }
    }
}

static void mul130(uint64_t *out, const uint64_t *x, const uint64_t *y) {
    /* schoolbook 3x3 then reduce mod 2^130-5.
       x = x0 + x1*2^64 + x2*2^128, x2 < 4 so x < 2^130
    */
    u128 p0 = (u128)x[0]*y[0];
    u128 p1 = (u128)x[0]*y[1] + (u128)x[1]*y[0];
    u128 p2 = (u128)x[0]*y[2] + (u128)x[1]*y[1] + (u128)x[2]*y[0];
    u128 p3 = (u128)x[1]*y[2] + (u128)x[2]*y[1];
    u128 p4 = (u128)x[2]*y[2];

    /* add carries from lower products */
    p1 += (uint64_t)(p0 >> 64);
    p2 += (uint64_t)(p1 >> 64);
    p3 += (uint64_t)(p2 >> 64);
    p4 += (uint64_t)(p3 >> 64);

    uint64_t z0 = (uint64_t)p0;
    uint64_t z1 = (uint64_t)p1;
    uint64_t z2 = (uint64_t)p2; /* includes bits above 130: z2 is the 2^128 limb, low 2 bits are in-range, rest is >= 2^130 */
    /* bits of product:
       z0 = bits 0..63
       z1 = bits 64..127
       z2 low 2 bits = bits 128..129
       remaining of z2 (>>2) plus p3, p4 are coefficients of 2^130 and higher.
       2^130 ≡ 5, 2^192 ≡ 5*2^62, etc. Let's collect the high part as an integer H such that
       product = (z0 + z1*2^64 + (z2&3)*2^128) + H * 2^130
       H = (z2>>2) + p3*2^(192-130) + p4*2^(256-130)
         = (z2>>2) + p3*2^62 + p4*2^126
       p3 and p4 may be larger than 64 bits. Handle carefully.
    */
    /* Build H = (z2>>2) + p3 << 62 + p4 << 126 */
