#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);
size_t Poly1305_ctx_size(void);

/* We will NOT use Poly1305_Final's pad; we'll get raw accumulator by a trick:
   Poly1305_Final adds pad. To get raw h, we can finalize with a known approach:
   Actually OpenSSL Poly1305_Final always adds s (pad). We can compute tag and also
   separately... For speed test we just time OpenSSL Poly1305_Update on chunks,
   then combine using our mul. Combining is tiny. The question is whether parallel
   Poly1305_Update is faster.
*/

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

typedef struct {
    const unsigned char *msg;
    size_t len;
    unsigned char key[32];
    unsigned char tag[16];
    size_t ctxsz;
} Job;

static void *worker(void *arg) {
    Job *j=arg;
    void *ctx=malloc(j->ctxsz);
    Poly1305_Init(ctx, j->key);
    Poly1305_Update(ctx, j->msg, j->len);
    Poly1305_Final(ctx, j->tag);
    free(ctx);
    return NULL;
}

int main() {
    size_t N=40u*1024*1024;
    N &= ~15ull;
    unsigned char *msg=malloc(N);
    FILE *f=fopen("/dev/urandom","rb"); fread(msg,1,N,f); fclose(f);
    unsigned char key[32];
    for(int i=0;i<32;i++) key[i]=i+1;
    size_t ctxsz=Poly1305_ctx_size();

    int reps=5;
    double t0=now();
    unsigned char tag[16];
    void *ctx=malloc(ctxsz);
    for(int i=0;i<reps;i++){
        Poly1305_Init(ctx, key);
        Poly1305_Update(ctx, msg, N);
        Poly1305_Final(ctx, tag);
    }
    printf("serial poly %.4f\n", (now()-t0)/reps);

    for (int nt=2; nt<=8; nt++) {
        t0=now();
        for(int r=0;r<reps;r++){
            pthread_t th[16];
            Job jobs[16];
            size_t chunk=(N/nt)&~15ull;
            size_t off=0;
            for(int i=0;i<nt;i++){
                size_t len=(i==nt-1)?(N-off):chunk;
                jobs[i].msg=msg+off;
                jobs[i].len=len;
                memcpy(jobs[i].key, key, 32);
                jobs[i].ctxsz=ctxsz;
                pthread_create(&th[i], NULL, worker, &jobs[i]);
                off+=len;
            }
            for(int i=0;i<nt;i++) pthread_join(th[i], NULL);
        }
        printf("par %d poly (no combine) %.4f\n", nt, (now()-t0)/reps);
    }
    return 0;
}
