typedef unsigned __int128 u128;

/* Multiply mod 2^130-5 using 44-bit limbs, which are easy and proven pattern. */
static void mul44(uint64_t h[3], const uint64_t r[3]) {
    uint64_t r0=r[0], r1=r[1], r2=r[2];
    uint64_t s1 = r1 * 5, s2 = r2 * 5;
    uint64_t h0=h[0], h1=h[1], h2=h[2];
    u128 d0 = (u128)h0*r0 + (u128)h1*s2 + (u128)h2*s1;
    u128 d1 = (u128)h0*r1 + (u128)h1*r0 + (u128)h2*s2;
    u128 d2 = (u128)h0*r2 + (u128)h1*r1 + (u128)h2*r0;
    uint64_t c = (uint64_t)(d0 >> 44); h0 = (uint64_t)d0 & ((1ull<<44)-1);
    d1 += c; c = (uint64_t)(d1 >> 44); h1 = (uint64_t)d1 & ((1ull<<44)-1);
    d2 += c; c = (uint64_t)(d2 >> 42); h2 = (uint64_t)d2 & ((1ull<<42)-1);
    u128 t = (u128)h0 + (u128)c * 5;
    h0 = (uint64_t)t & ((1ull<<44)-1);
    h1 += (uint64_t)(t >> 44);
    c = h1 >> 44; h1 &= (1ull<<44)-1; h2 += c;
    /* h2 might exceed 42 bits if c large, one more pass */
    c = h2 >> 42; h2 &= (1ull<<42)-1;
    t = (u128)h0 + (u128)c * 5;
    h0 = (uint64_t)t & ((1ull<<44)-1);
    h1 += (uint64_t)(t >> 44);
    c = h1 >> 44; h1 &= (1ull<<44)-1; h2 += c;
    h[0]=h0; h[1]=h1; h[2]=h2;
}
static void add44(uint64_t h[3], const uint64_t m[3]) {
    h[0]+=m[0]; h[1]+=m[1]; h[2]+=m[2];
    uint64_t c=h[0]>>44; h[0]&=(1ull<<44)-1; h[1]+=c;
    c=h[1]>>44; h[1]&=(1ull<<44)-1; h[2]+=c;
    c=h[2]>>42; h[2]&=(1ull<<42)-1;
    u128 t=(u128)h[0]+(u128)c*5;
    h[0]=(uint64_t)t & ((1ull<<44)-1);
    h[1]+=(uint64_t)(t>>44);
    c=h[1]>>44; h[1]&=(1ull<<44)-1; h[2]+=c;
