    int have_aad = (aad_o != Py_None && aad_o != NULL);
    if (have_aad) {
        if (PyObject_GetBuffer(aad_o, &aad, PyBUF_SIMPLE) < 0) {
            PyBuffer_Release(&pt); PyBuffer_Release(&nonce); PyBuffer_Release(&key);
            return NULL;
        }
    }
    if (key.len != 32 || nonce.len != 12) {
        PyErr_SetString(PyExc_ValueError, "bad key/nonce size");
        goto fail;
    }

    size_t n = (size_t)pt.len;
    size_t aad_len = have_aad ? (size_t)aad.len : 0;
    const unsigned char *aad_buf = have_aad ? (const unsigned char *)aad.buf : NULL;

    PyObject *ct_o = PyBytes_FromStringAndSize(NULL, (Py_ssize_t)n);
    if (!ct_o) goto fail;
    unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_o);

    unsigned int kwords[8], nwords[3];
    memcpy(kwords, key.buf, 32);
    memcpy(nwords, nonce.buf, 12);

    unsigned char block0[64];
    unsigned char zeros[64] = {0};
    unsigned int c0[4] = {0, nwords[0], nwords[1], nwords[2]};
    ChaCha20_ctr32(block0, zeros, 64, kwords, c0);

    static size_t ctxsz = 0;
    if (!ctxsz) ctxsz = Poly1305_ctx_size();

    size_t full = n & ~(size_t)15;
    size_t tail = n - full;

    int nt = 1;
    if (full >= (1u << 20)) {
        nt = g_threads;
        if (nt < 1) nt = 1;
        if (nt > MAX_THREADS) nt = MAX_THREADS;
    }

    pthread_t th[MAX_THREADS];
    Job jobs[MAX_THREADS];
    size_t chunk = full;
    if (nt > 1) {
        chunk = (full / (size_t)nt) & ~(size_t)15;
        if (chunk == 0) nt = 1;
    }
    size_t off = 0;
    unsigned int ctr = 1;
    int spawned = 0;
    int nj = nt;
    for (int i = 0; i < nj; i++) {
        size_t len = (i == nj - 1) ? (full - off) : chunk;
        memset(&jobs[i], 0, sizeof(jobs[i]));
        jobs[i].out = ct + off;
        jobs[i].in = (const unsigned char *)pt.buf + off;
        jobs[i].len = len;
        jobs[i].counter = ctr;
        jobs[i].nonce[0] = nwords[0];
        jobs[i].nonce[1] = nwords[1];
        jobs[i].nonce[2] = nwords[2];
        memcpy(jobs[i].key, kwords, 32);
        memcpy(jobs[i].polykey, block0, 32);
        jobs[i].ctxsz = ctxsz;
        ctr += (unsigned int)((len + 63) / 64);
        off += len;
        if (nt == 1) {
            worker(&jobs[i]);
        } else {
            pthread_create(&th[i], NULL, worker, &jobs[i]);
            spawned++;
        }
    }
    for (int i = 0; i < spawned; i++) pthread_join(th[i], NULL);

    /* encrypt tail with continuing counter (not included in parallel poly) */
    if (tail) {
        unsigned int ctail[4] = {ctr, nwords[0], nwords[1], nwords[2]};
        ChaCha20_ctr32(ct + full, (const unsigned char *)pt.buf + full, tail, kwords, ctail);
    }

    uint64_t r[3];
    clamp_r(r, block0);

    uint64_t acc[3] = {0, 0, 0};
    /* prefix = pad16(aad) */
    size_t prefix_len = 0;
    if (aad_len) {
        prefix_len = (aad_len + 15) & ~(size_t)15;
        unsigned char prefix[128];
        /* aad is small in this task (32 bytes) but be safe */
        unsigned char *pref = prefix;
        unsigned char *heap = NULL;
        if (prefix_len > sizeof(prefix)) {
            heap = (unsigned char *)calloc(1, prefix_len);
            pref = heap;
        } else {
            memset(prefix, 0, prefix_len);
        }
        memcpy(pref, aad_buf, aad_len);
        void *pctx = malloc(ctxsz);
        Poly1305_Init(pctx, block0);
        Poly1305_Update(pctx, pref, prefix_len);
        memcpy(acc, pctx, 17);
        acc[2] &= 0xff;
        free(pctx);
        free(heap);
    }

    size_t full_blocks = full / 16;
    if (full_blocks && prefix_len) {
        uint64_t pw[3], t[3];
        pow130(pw, r, full_blocks);
        mul130(t, acc, pw);
        memcpy(acc, t, 24);
    }

    /* combine chunk accumulators: sum H_i * r^{blocks after i} */
    size_t blocks_after = 0;
    for (int i = nj - 1; i >= 0; i--) {
        if (jobs[i].len == 0) continue;
        uint64_t term[3];
        if (blocks_after) {
            uint64_t pw[3];
            pow130(pw, r, blocks_after);
            mul130(term, jobs[i].h, pw);
        } else {
            memcpy(term, jobs[i].h, 24);
        }
        add130(acc, term);
        blocks_after += jobs[i].len / 16;
    }

    if (tail) {
        unsigned char last[16] = {0};
        memcpy(last, ct + full, tail);
        /* zero-padded full block WITH hibit, processed as a normal poly block */
        void *pctx = malloc(ctxsz);
        Poly1305_Init(pctx, block0);
        Poly1305_Update(pctx, last, 16);
        uint64_t th[3] = {0, 0, 0};
        memcpy(th, pctx, 17);
        th[2] &= 0xff;
        free(pctx);
        add130(acc, th);
    }

    /* lengths block */
    unsigned char lens[16];
    uint64_t la = aad_len, lp = n;
    memcpy(lens, &la, 8);
    memcpy(lens + 8, &lp, 8);
    {
        void *pctx = malloc(ctxsz);
        Poly1305_Init(pctx, block0);
        Poly1305_Update(pctx, lens, 16);
        uint64_t th[3] = {0, 0, 0};
        memcpy(th, pctx, 17);
        th[2] &= 0xff;
        free(pctx);
        add130(acc, th);
    }

    freeze(acc);
    uint64_t pad0, pad1;
    memcpy(&pad0, block0 + 16, 8);
    memcpy(&pad1, block0 + 24, 8);
    u128 s0 = (u128)acc[0] + pad0;
    u128 s1 = (u128)acc[1] + pad1 + (uint64_t)(s0 >> 64);
    uint64_t o0 = (uint64_t)s0, o1 = (uint64_t)s1;
    unsigned char tag[16];
    memcpy(tag, &o0, 8);
    memcpy(tag + 8, &o1, 8);

    PyObject *tag_o = PyBytes_FromStringAndSize((char *)tag, 16);
    if (!tag_o) { Py_DECREF(ct_o); goto fail; }
    PyObject *res = PyTuple_New(2);
    PyTuple_SET_ITEM(res, 0, ct_o);
    PyTuple_SET_ITEM(res, 1, tag_o);

    PyBuffer_Release(&pt);
    PyBuffer_Release(&nonce);
    PyBuffer_Release(&key);
    if (have_aad) PyBuffer_Release(&aad);
    return res;

fail:
    PyBuffer_Release(&pt);
    PyBuffer_Release(&nonce);
    PyBuffer_Release(&key);
    if (have_aad) PyBuffer_Release(&aad);
    return NULL;
}

static PyMethodDef methods[] = {
    {"encrypt", py_encrypt, METH_VARARGS, "ChaCha20-Poly1305 encrypt"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "fastchacha", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_fastchacha(void) { return PyModule_Create(&moduledef); }
